import { readFile } from "node:fs/promises";
import path from "node:path";
import { parseFrontMatter } from "../kb/frontmatter";
import { defaultContentRoot } from "../kb/load-articles";

export type SafetyResponseKind =
  "urgent" | "self-harm" | "no-reliable-information" | "out-of-scope";

export interface SafetyResponse {
  title: string;
  body: string;
}

const cache = new Map<string, SafetyResponse>();

/**
 * Loads the pre-written, clinician-reviewable fixed response for urgent /
 * self-harm messages from content/{locale}/safety/{kind}.md — these are
 * never generated by the LLM (spec: "return a fixed, pre-written response
 * from content, not generated").
 */
export async function loadFixedResponse(
  kind: SafetyResponseKind,
  locale: string,
  contentRoot: string = defaultContentRoot(),
): Promise<SafetyResponse> {
  const cacheKey = `${contentRoot}:${locale}:${kind}`;
  const cached = cache.get(cacheKey);
  if (cached) return cached;

  const filePath = path.join(contentRoot, locale, "safety", `${kind}.md`);
  const raw = await readFile(filePath, "utf8");
  const { frontMatter, body } = parseFrontMatter(raw);
  const response: SafetyResponse = { title: frontMatter.title, body };
  cache.set(cacheKey, response);
  return response;
}
